t final answer: '(' * minO + t_best + ')' * (S + minO)\n    string t_best = s.substr(best_k) + s.substr(0, best_k);\n    string ans;\n    ans.reserve((size_t)n + (size_t)minO + (size_t)(S + minO));\n    ans.append((size_t)minO, '(');\n    ans += t_best;\n    ans.append((size_t)(S + minO), ')');\n\n    cout << ans << \"\\n\";\n    return 0;\n}\nCPP\n",
